lxml.html.soupparser._parse:
def _parse(source, beautifulsoup, makeelement, **bsargs):
    if beautifulsoup is None:
        beautifulsoup = BeautifulSoup
    if hasattr(beautifulsoup, 'HTML_ENTITIES'):
        if 'convertEntities' not in bsargs:
            bsargs['convertEntities'] = 'html'
    if hasattr(beautifulsoup, 'DEFAULT_BUILDER_FEATURES'):
        if 'features' not in bsargs:
            bsargs['features'] = 'html.parser'
    tree = beautifulsoup(source, **bsargs)
    root = _convert_tree(tree, makeelement)
    if (len(root) == 1 and root[0].tag == 'html'):
        return root[0]
    root.tag = 'html'
    return root

lxml.html.formfill._find_form_ids:
def _find_form_ids(el):
    forms = _forms_xpath(el)
    if not forms:
        yield '(no forms)'
        return
    for (index, form) in enumerate(forms):
        if form.get('id'):
            if form.get('name'):
                yield '%s or %s' % (form.get('id'), form.get('name'))
            else:
                yield form.get('id')
        elif form.get('name'):
            yield form.get('name')
        else:
            yield '(unnamed form %s)' % index

requests.help._implementation:
def _implementation():
    """Return a dict with the Python implementation and version.

    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.

    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()
    if implementation == 'CPython':
        implementation_version = platform.python_version()
    elif implementation == 'PyPy':
        implementation_version = '{}.{}.{}'.format(sys.pypy_version_info.major, sys.pypy_version_info.minor, sys.pypy_version_info.micro)
        if sys.pypy_version_info.releaselevel != 'final':
            implementation_version = ''.join([implementation_version, sys.pypy_version_info.releaselevel])
    elif implementation == 'Jython':
        implementation_version = platform.python_version()
    elif implementation == 'IronPython':
        implementation_version = platform.python_version()
    else:
        implementation_version = 'Unknown'
    return {'name': implementation, 'version': implementation_version}

lxml.html.soupparser._convert_tree:
def _convert_tree(beautiful_soup_tree, makeelement):
    if makeelement is None:
        makeelement = html.html_parser.makeelement
    first_element_idx = last_element_idx = None
    html_root = declaration = None
    for (i, e) in enumerate(beautiful_soup_tree):
        if isinstance(e, Tag):
            if first_element_idx is None:
                first_element_idx = i
            last_element_idx = i
            if (html_root is None and e.name and e.name.lower() == 'html'):
                html_root = e
        elif (declaration is None and isinstance(e, _DECLARATION_OR_DOCTYPE)):
            declaration = e
    if first_element_idx is None:
        pre_root = post_root = []
        roots = beautiful_soup_tree.contents
    else:
        pre_root = beautiful_soup_tree.contents[:first_element_idx]
        roots = beautiful_soup_tree.contents[first_element_idx:last_element_idx + 1]
        post_root = beautiful_soup_tree.contents[last_element_idx + 1:]
    if html_root is not None:
        i = roots.index(html_root)
        html_root.contents = roots[:i] + html_root.contents + roots[i + 1:]
    else:
        html_root = _PseudoTag(roots)
    convert_node = _init_node_converters(makeelement)
    res_root = convert_node(html_root)
    prev = res_root
    for e in reversed(pre_root):
        converted = convert_node(e)
        if converted is not None:
            prev.addprevious(converted)
            prev = converted
    prev = res_root
    for e in post_root:
        converted = convert_node(e)
        if converted is not None:
            prev.addnext(converted)
            prev = converted
    if declaration is not None:
        try:
            doctype_string = declaration.output_ready()
        except AttributeError:
            doctype_string = declaration.string
        match = _parse_doctype_declaration(doctype_string)
        if not match:
            pass
        else:
            (external_id, sys_uri) = match.groups()
            docinfo = res_root.getroottree().docinfo
            docinfo.public_id = (external_id and external_id[1:-1])
            docinfo.system_url = (sys_uri and sys_uri[1:-1])
    return res_root

urllib3.packages.six.with_metaclass:
def with_metaclass(meta, *bases):
    """Create a base class with a metaclass."""


    class metaclass(type):

        def __new__(cls, name, this_bases, d):
            if sys.version_info[:2] >= (3, 7):
                resolved_bases = types.resolve_bases(bases)
                if resolved_bases is not bases:
                    d['__orig_bases__'] = bases
            else:
                resolved_bases = bases
            return meta(name, resolved_bases, d)

        @classmethod
        def __prepare__(cls, name, this_bases):
            return meta.__prepare__(name, bases)

    return type.__new__(metaclass, 'temporary_class', (), {})

lxml.html.formfill._check:
def _check(el, check):
    if check:
        el.set('checked', '')
    elif 'checked' in el.attrib:
        del el.attrib['checked']

lxml.html.diff.locate_unbalanced_end:
def locate_unbalanced_end(unbalanced_end, pre_delete, post_delete):
    """ like locate_unbalanced_start, except handling end tags and
    possibly moving the point earlier in the document.  """
    while 1:
        if not unbalanced_end:
            break
        finding = unbalanced_end[-1]
        finding_name = finding.split()[0].strip('<>/')
        if not pre_delete:
            break
        next = pre_delete[-1]
        if (next is DEL_END or not next.startswith('</')):
            break
        name = next.split()[0].strip('<>/')
        if (name == 'ins' or name == 'del'):
            break
        if name == finding_name:
            unbalanced_end.pop()
            post_delete.insert(0, pre_delete.pop())
        else:
            break
